python3 - <<'PY'
import socket, time, subprocess, os, signal, binascii
payloads=[]
# Generate bounded malformed PFCP-ish datagrams
for n in range(0, 40):
    payloads.append(bytes([0])*n)
for flags in [0x00,0x20,0x21,0x28,0x30,0xff]:
  for mt in [0,1,2,5,50,52,255]:
    for ln in [0,1,3,4,5,7,8,12,65535]:
      p=bytes([flags,mt,(ln>>8)&255,ln&255])+b'\x00\x00\x11\x00'+b'A'*min(ln,32)
      payloads.append(p)
# some with S flag and short lengths
for l in range(0,25):
    payloads.append(bytes.fromhex('21 32 00 01')+bytes(range(l)))

s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
s.bind(('127.0.0.1',0))
s.settimeout(0.05)
count=0; replies=0
for p in payloads:
    count+=1
    try:
        s.sendto(p,('127.0.0.1',8805))
        try:
            while True:
                d,a=s.recvfrom(65535); replies+=1; print('reply', count, binascii.hexlify(d[:64]).decode())
        except socket.timeout: pass
    except Exception as e:
        print('senderr', count, e)
    time.sleep(0.01)
print('sent',count,'replies',replies)
PY

